// swift-tools-version: 5.9
// dusimagez — Swift (iOS/macOS) bindings, SwiftPM package.
//
// The Swift API is generated by uniffi-bindgen 0.29 from
// ../../crates/dusimagez/src/dusimagez.udl and checked in under
// Sources/Dusimagez/ (see scripts/regenerate-bindings.sh).
//
// Linking the Rust core: SwiftPM cannot build Rust. CI (mobile.yml,
// macos-latest) builds the static library first
// (`cargo build --release -p dusimagez-uniffi` — the scaffolding
// crate, whose [lib] name is `uniffi_dusimagez`) and then runs:
//
//     swift test -Xlinker -L<dir-with-libuniffi_dusimagez.a> -Xlinker -luniffi_dusimagez
//
// The `DusimagezFFI` system-library target below exposes the C header
// uniffi-bindgen generates (`dusimagezFFI.h` + modulemap); the
// generated `dusimagez.swift` calls those C symbols, which resolve
// from libuniffi_dusimagez.a at link time. Do NOT claim a Linux iOS build:
// iOS/macOS targets need macOS (macos-latest in CI).
import PackageDescription

let package = Package(
    name: "dusimagez",
    platforms: [
        .iOS(.v15),
        .macOS(.v12),
    ],
    products: [
        .library(name: "Dusimagez", targets: ["Dusimagez"]),
    ],
    targets: [
        // C header + modulemap generated by uniffi-bindgen alongside
        // the Swift bindings. The symbols come from
        // libuniffi_dusimagez.a.
        .systemLibrary(
            name: "DusimagezFFI",
            path: "Sources/DusimagezFFI"
        ),
        .target(
            name: "Dusimagez",
            dependencies: ["DusimagezFFI"],
            path: "Sources/Dusimagez"
        ),
        .testTarget(
            name: "DusimagezTests",
            dependencies: ["Dusimagez"],
            path: "Tests/DusimagezTests"
        ),
    ]
)
